<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); try { $res = App\Models\PurchaseItem::selectRaw("name, category, SUM(count) as units_sold, SUM(count * price) as total_income")->groupBy("name", "category")->orderBy("total_income", "desc")->get(); print_r($res->toArray()); } catch(Exception $e) { echo $e->getMessage(); }
